  Lemma bufW_facts : forall A vm M buf cap, sideW A vm M buf cap ->
    (0x6b000 <= bv_unsigned buf)%Z /\ (bv_unsigned buf + cap <= bv_unsigned sp0 - 8388608)%Z /\ (bv_unsigned buf mod 16 = 0)%Z
